-- Contenu « theme_amour » — généré par scripts/content-migration.ts (50 questions).
-- Mise à jour uniquement des questions jamais modifiées dans le back-office (admin_edited_at null).
on conflict (id) do update set
  theme = excluded.theme,
  type = excluded.type,
  prompt = excluded.prompt,
  unit = excluded.unit,
  answer = excluded.answer,
  items = excluded.items,
  year = excluded.year,
  tolerance = excluded.tolerance,
  subject = excluded.subject,
  source = excluded.source,
  source_url = excluded.source_url,
  perishable = excluded.perishable,
  difficulty = excluded.difficulty,
  status = excluded.status,
  verified_at = excluded.verified_at,
  review_due_at = excluded.review_due_at,
  notes = excluded.notes
where public.questions.admin_edited_at is null;
