insert into public.questions (id, pack_id, theme, type, prompt, unit, answer, items, year, tolerance, subject, source, source_url, perishable, difficulty, status, verified_at, review_due_at, notes)
values
('amour-001', 'classique', 'amour', 'number'::public.question_type, 'Selon le Guinness, environ combien d’années a duré le plus long mariage jamais homologué, celui de David et Sarah Hiller (1809-1898) ?', 'ans', 89, null, false, null, 'mariage-hiller', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/longest-marriage', false, 2, 'published'::public.question_status, '2026-10-20', null, 'GWR : 88 ans et 349 jours (23/04/1809 – 08/04/1898). Accepter 89. Réponse arrondie à 89 (88 ans et 349 jours).'),
('amour-002', 'classique', 'amour', 'number'::public.question_type, 'Combien d’années ont duré les fiançailles d’Octavio Guillén et Adriana Martínez (Mexique), les plus longues fiançailles jamais recensées ?', 'ans', 67, null, false, null, 'fiancailles-longues', 'Guinness World Records', 'https://www.guinnessworldrecords.com/news/2013/2/valentines-day-10-of-the-most-romantic-world-records-47017', false, 1, 'published'::public.question_status, '2026-10-20', null, 'GWR : 67 ans, mariage en juin 1969 à Mexico, tous deux âgés de 82 ans.'),
('amour-003', 'classique', 'amour', 'number'::public.question_type, 'Combien de fois s’est marié l’Américain Glynn « Scotty » Wolfe, l’homme le plus marié du monde (mariages successifs) selon le Guinness ?', '', 29, null, false, null, 'glynn-wolfe', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/65107-most-monogamous-marriages-by-a-male', false, 1, 'published'::public.question_status, '2026-10-20', null, 'GWR : 29 mariages monogames successifs (1908-1997). Certaines sources disent 31 en comptant des annulations ; on suit le Guinness.'),
('amour-004', 'classique', 'amour', 'number'::public.question_type, 'Combien de fois s’est mariée l’Américaine Linda Essex, la femme qui détient le record du plus grand nombre de mariages selon le Guinness ?', '', 23, null, false, null, 'linda-essex', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/65105-most-monogamous-marriages-by-a-female', false, 2, 'published'::public.question_status, '2026-10-20', null, 'GWR : 23 mariages monogames successifs. Son dernier mari était Glynn Wolfe (autre question, sujet distinct).'),
('amour-005', 'classique', 'amour', 'number'::public.question_type, 'En 2024, à Philadelphie, quel âge cumulaient Marjorie Fiterman et Bernie Littman, les plus vieux jeunes mariés du monde selon le Guinness ?', 'ans', 202, null, false, null, 'jeunes-maries-ages', 'Guinness World Records', 'https://www.nbcnews.com/news/us-news/spouses-combined-age-202-become-worlds-oldest-newlyweds-rcna184095', false, 1, 'published'::public.question_status, '2026-10-20', null, 'Mariage le 19/05/2024 : elle 102 ans, lui 100 ans. GWR : 202 ans et 271 jours cumulés.'),
('amour-006', 'classique', 'amour', 'number'::public.question_type, 'Combien de tonnes pesait le plus gros gâteau de mariage du monde, présenté en 2004 dans un casino du Connecticut ?', 'tonnes', 6.8, null, false, null, 'gateau-mariage', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/largest-wedding-cake', false, 3, 'published'::public.question_status, '2026-10-20', null, 'GWR : 6,818 t (15 032 lb), Mohegan Sun, 08/02/2004.'),
('amour-007', 'classique', 'amour', 'number'::public.question_type, 'Combien de mètres mesurait le plus long bouquet de mariée du monde, composé de 9 400 fleurs en Inde en 2023 ?', 'm', 136.7, null, false, null, 'bouquet-mariee', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/largest-wedding-bouquet', false, 3, 'published'::public.question_status, '2026-10-20', null, 'GWR : 136,7 m, Bangalore, 22/01/2023. Le nombre de fleurs est donné dans l’énoncé, pas la réponse.'),
('amour-008', 'classique', 'amour', 'number'::public.question_type, 'Combien de demoiselles d’honneur accompagnaient Tina Ackles lors de son mariage en Floride en 2015, le record mondial pour une seule mariée ?', '', 168, null, false, null, 'demoiselles-honneur', 'Guinness World Records', 'https://www.guinnessworldrecords.com/news/2023/9/there-was-so-much-love-and-laughter-record-setting-bride-had-168-bridesmaids', false, 2, 'published'::public.question_status, '2026-10-20', null, 'GWR : 168 demoiselles d’honneur, 18/04/2015. Une revendication nigériane (200) n’est pas homologuée.'),
('amour-009', 'classique', 'amour', 'number'::public.question_type, 'Combien de couples se sont mariés en moins de 12 heures à Baran (Inde) en 2023, le plus grand mariage collectif jamais homologué sur une journée ?', 'couples', 2143, null, false, null, 'mariage-collectif', 'Guinness World Records', 'https://www.guinnessworldrecords.com/news/2023/6/record-breaking-mass-wedding-sees-4-286-indians-make-ultimate-commitment-752302', false, 3, 'published'::public.question_status, '2026-10-20', null, 'GWR : 2 143 couples (4 286 personnes), records « most couples married in 12 hours » et « in 24 hours ». Record précédent : 963 couples (Yémen, 2013).'),
('amour-010', 'classique', 'amour', 'number'::public.question_type, 'Combien de couples se sont embrassés en même temps à São Paulo en 2014, le plus grand baiser collectif jamais homologué ?', 'couples', 13577, null, false, null, 'baiser-collectif', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/most-couples-kissing-simultaneously', false, 3, 'published'::public.question_status, '2026-10-20', null, 'GWR : 13 577 couples, Carnafacul 2014, 17/05/2014.'),
('amour-011', 'classique', 'amour', 'number'::public.question_type, 'Combien de secondes a duré le plus long baiser sous l’eau en apnée, homologué aux Maldives en 2023 (record en 2026) ?', 'secondes', 246, null, false, null, 'baiser-sous-marin', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/longest-underwater-kiss-(apnea)-', true, 2, 'published'::public.question_status, '2026-10-20', '2027-04-20', 'GWR : 4 min 6 s = 246 s, Beth Neale et Miles Cloutier, 04/02/2023. Record susceptible d’être battu.'),
('amour-012', 'classique', 'amour', 'number'::public.question_type, 'Combien de secondes dure « The Kiss » (1896) de Thomas Edison, le tout premier baiser de l’histoire du cinéma ?', 'secondes', 18, null, false, null, 'premier-baiser-cinema', 'Library of Congress', 'https://www.loc.gov/item/00694131/', false, 1, 'published'::public.question_status, '2026-10-20', null, 'Notice LOC : durée 0:18. Le Guinness le cite comme premier baiser à l’écran (article 2024).'),
('amour-013', 'classique', 'amour', 'number'::public.question_type, 'En quelle année Richard Cadbury a-t-il créé la plus ancienne boîte de chocolats en forme de cœur connue pour la Saint-Valentin ?', '', 1868, null, true, null, 'boite-coeur-cadbury', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/100099-earliest-box-of-valentines-day-chocolates', false, 3, 'published'::public.question_status, '2026-10-20', null, 'GWR : 1868. Quelques sites disent 1861 (année de reprise de l’entreprise) : erreur.'),
('amour-014', 'classique', 'amour', 'number'::public.question_type, 'Selon la National Retail Federation, combien de milliards de dollars les Américains prévoyaient-ils de dépenser pour la Saint-Valentin 2026, un record historique ?', 'milliards de dollars', 29.1, null, false, null, 'saint-valentin-depenses', 'National Retail Federation', 'https://nrf.com/media-center/press-releases/valentine-s-day-spending-expected-to-reach-new-records', true, 2, 'published'::public.question_status, '2026-10-20', '2027-04-20', 'NRF (27/01/2026) : prévision record de 29,1 Md$, contre 27,5 Md$ en 2025 (précédent record). Chiffre d’enquête prévisionnelle.'),
('amour-015', 'classique', 'amour', 'number'::public.question_type, 'Selon l’étude de Stanford « How Couples Meet » (2017), quel pourcentage des couples hétérosexuels américains s’étaient rencontrés en ligne, devenu le mode de rencontre le plus fréquent ?', '%', 39, null, false, null, 'rencontres-en-ligne', 'Université Stanford (Rosenfeld et al., PNAS 2019)', 'https://news.stanford.edu/stories/2019/08/online-dating-popular-way-u-s-couples-meet', false, 1, 'published'::public.question_status, '2026-10-20', null, 'Stanford News : environ 39 % en 2017 contre 22 % en 2009.'),
('amour-016', 'classique', 'amour', 'number'::public.question_type, 'En 2026, combien de milliards de « matchs » revendique Tinder, l’application de rencontre la plus téléchargée au monde, depuis son lancement ?', 'milliards', 100, null, false, null, 'tinder-matchs', 'Tinder (salle de presse)', 'https://www.tinderpressroom.com/about', true, 2, 'review'::public.question_status, '2026-10-20', '2027-04-20', 'Site officiel : « 100+ billion total matches » et plus de 630 millions de téléchargements. Chiffre arrondi revendiqué par l’entreprise. À relire : chiffre arrondi ou record non confirmé récemment.'),
('amour-017', 'classique', 'amour', 'number'::public.question_type, 'Combien de milliers de mariages ont été célébrés en France métropolitaine en 1920, l’année record de tout le XXe siècle ?', 'milliers', 623, null, false, null, 'mariages-1920', 'Insee', 'https://www.insee.fr/fr/statistiques/8721187', false, 3, 'published'::public.question_status, '2026-10-20', null, 'Insee, tableau MAR1 (métropole) : 622 724 mariages en 1920 (rattrapage d’après-guerre), devant 1919 (552 683) et 1946 (516 882).'),
('amour-018', 'classique', 'amour', 'number'::public.question_type, 'Quel était en 2024 l’âge moyen des femmes au mariage en France (couples de sexe différent), le plus élevé jamais mesuré par l’Insee ?', 'ans', 37.6, null, false, null, 'age-mariees-2024', 'Insee', 'https://www.insee.fr/fr/statistiques/8721187', false, 2, 'published'::public.question_status, '2026-10-20', null, 'Insee MAR2 : 37,6 ans en 2023 et 2024 (record), 37,5 en 2025 provisoire. Hommes : 40,0 en 2023.'),
('amour-019', 'classique', 'amour', 'number'::public.question_type, 'En 1972, année où les Françaises se mariaient le plus jeune, quel était leur âge moyen au mariage ?', 'ans', 23.7, null, false, null, 'age-mariees-1972', 'Insee', 'https://www.insee.fr/fr/statistiques/8721187', false, 2, 'published'::public.question_status, '2026-10-20', null, 'Insee MAR2 (métropole) : 23,7 ans en 1972, minimum de la série depuis 1946.'),
('amour-020', 'classique', 'amour', 'number'::public.question_type, 'Combien de milliers de PACS ont été conclus en France en 2021, l’année record depuis la création du pacte civil de solidarité ?', 'milliers', 209, null, false, null, 'pacs-record', 'Insee', 'https://www.insee.fr/fr/statistiques/8721187', false, 2, 'published'::public.question_status, '2026-10-20', null, 'Insee MAR3 : 209 461 en 2021, quasi à égalité avec 2018 (209 349). 197 176 en 2024.'),
('amour-021', 'classique', 'amour', 'number'::public.question_type, 'Combien de milliers de divorces ont été prononcés en France en 2005, l’année record après la réforme qui a simplifié les procédures ?', 'milliers', 155, null, false, null, 'divorces-2005', 'Insee', 'https://insee.fr/fr/statistiques/2121566', false, 3, 'published'::public.question_status, '2026-10-20', null, 'Insee Première n°1599 : pic à 155 300 divorces en 2005 (loi du 26 mai 2004 entrée en vigueur au 1er janvier 2005).'),
('amour-022', 'classique', 'amour', 'number'::public.question_type, 'En 2014, l’année record, combien de mariages entre personnes de même sexe ont été célébrés en France ?', 'mariages', 10522, null, false, null, 'mariages-meme-sexe', 'Insee', 'https://www.insee.fr/fr/statistiques/8721187', false, 2, 'published'::public.question_status, '2026-10-20', null, 'Insee MAR1 : 10 522 en 2014 (effet de rattrapage après l’ouverture en mai 2013), environ 7 000 en 2025.'),
('amour-023', 'classique', 'amour', 'number'::public.question_type, 'Combien de milliers de bébés sont nés en France en 2025, le plus faible nombre de naissances depuis 1942 ?', 'milliers', 645, null, false, null, 'naissances-2025', 'Insee', 'https://www.insee.fr/fr/statistiques/8719824', false, 1, 'published'::public.question_status, '2026-10-20', null, 'Insee Première (bilan 2025) : environ 645 000 naissances, solde naturel négatif pour la première fois depuis 1945.'),
('amour-024', 'classique', 'amour', 'number'::public.question_type, 'En 2025, quel était l’âge moyen des mères à l’accouchement en France, le plus élevé jamais enregistré ?', 'ans', 31.2, null, false, null, 'age-meres', 'Insee', 'https://www.insee.fr/fr/statistiques/8719824', false, 1, 'published'::public.question_status, '2026-10-20', null, 'Insee bilan 2025 : 31,2 ans (29,6 en 2005). Pères : 34,1 ans.'),
('amour-025', 'classique', 'amour', 'number'::public.question_type, 'Combien d’enfants par femme comptait la France en 2025, l’indicateur de fécondité le plus bas depuis la fin de la Première Guerre mondiale ?', 'enfants par femme', 1.56, null, false, null, 'fecondite-2025', 'Insee', 'https://www.insee.fr/fr/statistiques/8719824', false, 2, 'published'::public.question_status, '2026-10-20', null, 'Insee bilan 2025 : 1,56 (1,61 en 2024).'),
('amour-026', 'classique', 'amour', 'number'::public.question_type, 'Selon la plus vaste étude jamais menée sur les naissances de jumeaux (165 pays, 2021), un enfant sur combien naît jumeau dans le monde ?', '', 42, null, false, null, 'jumeaux-proportion', 'ESHRE / Human Reproduction (Monden, Pison, Smits)', 'https://www.focusonreproduction.eu/press-releases/twin-peaks-more-twinning-in-humans-than-ever-before/', false, 2, 'published'::public.question_status, '2026-10-20', null, 'Environ 1,6 million de jumeaux par an ; taux passé de 9 à 12 pour 1 000 accouchements depuis les années 1980.'),
('amour-027', 'classique', 'amour', 'number'::public.question_type, 'Quel âge avaient Umeno Sumiyama et Koume Kodama en 2021, les plus vieilles jumelles identiques de l’histoire selon le Guinness ?', 'ans', 107, null, false, null, 'jumelles-agees', 'Guinness World Records', 'https://www.guinnessworldrecords.com/news/2021/9/107-year-old-japanese-sisters-confirmed-as-worlds-oldest-identical-twins-675690', false, 1, 'published'::public.question_status, '2026-10-20', null, 'GWR : 107 ans et 300 jours au 1er septembre 2021 (nées le 5 novembre 1913).'),
('amour-028', 'classique', 'amour', 'number'::public.question_type, 'Combien de chatons a mis au monde Dusty, une chatte texane, la plus prolifique de l’histoire selon le Guinness ?', 'chatons', 420, null, false, null, 'chatte-dusty', 'Guinness World Records', 'https://www.guinnessworldrecords.com/news/2017/8/international-cat-day-a-timeline-of-the-worlds-most-fascinating-feline-record-b-485212', false, 2, 'published'::public.question_status, '2026-10-20', null, 'GWR : 420 chatons ; dernière portée le 12 juin 1952.'),
('amour-029', 'classique', 'amour', 'number'::public.question_type, 'Combien de chatons comptait la plus grande portée de chat domestique jamais recensée par le Guinness (Royaume-Uni, 1970) ?', 'chatons', 19, null, false, null, 'portee-chat', 'Guinness World Records', 'https://www.guinnessworldrecords.com/news/2017/8/international-cat-day-a-timeline-of-the-worlds-most-fascinating-feline-record-b-485212', false, 2, 'review'::public.question_status, '2026-10-20', null, 'GWR (article 2017) : 19 chatons, croisement birman-siamois, 1970. À relire : chiffre arrondi ou record non confirmé récemment.'),
('amour-030', 'classique', 'amour', 'number'::public.question_type, 'Combien de chiots comptait la plus grande portée de chiens du monde, née en 2004 d’une mâtine napolitaine nommée Tia ?', 'chiots', 24, null, false, null, 'portee-chien', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/largest-litter-dog/', false, 1, 'published'::public.question_status, '2026-10-20', null, 'GWR : 24 chiots (9 femelles, 15 mâles), 29/11/2004, Cambridgeshire.'),
('amour-031', 'classique', 'amour', 'number'::public.question_type, 'Combien de petits comptait la plus grande portée jamais recensée chez un mammifère sauvage, celle d’un tenrec de Madagascar ?', 'petits', 31, null, false, null, 'portee-tenrec', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/70477-largest-litter-wild-mammal', false, 3, 'published'::public.question_status, '2026-10-20', null, 'GWR : 31 petits (30 survivants), tenrec commun (Tenrec ecaudatus). Certaines sources disent « jusqu’à 32 » (écart ~3 %).'),
('amour-032', 'classique', 'amour', 'number'::public.question_type, 'Combien de millions d’œufs contenaient les ovaires d’un poisson-lune, l’animal le plus fécond du monde selon le Guinness ?', 'millions', 300, null, false, null, 'poisson-lune-oeufs', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/69443-most-fertile-fish', false, 2, 'published'::public.question_status, '2026-10-20', null, 'GWR : 300 millions d’œufs (comptage des années 1920 ; l’espèce exacte du spécimen est discutée).'),
('amour-033', 'classique', 'amour', 'number'::public.question_type, 'À quel âge estimé Wisdom, l’albatros de Laysan, a-t-elle pondu un nouvel œuf fin 2024, faisant d’elle le plus vieil oiseau sauvage connu ?', 'ans', 74, null, false, null, 'albatros-wisdom', 'NPR', 'https://www.npr.org/2025/02/14/nx-s1-5297871/wisdom-albatross-mother-midway', false, 2, 'published'::public.question_status, '2026-10-20', null, 'Baguée adulte en 1956 ; âge estimé à au moins 74 ans. Poussin éclos le 30/01/2025 sur l’atoll de Midway.'),
('amour-034', 'classique', 'amour', 'number'::public.question_type, 'Combien d’années les cigales périodiques à cycle le plus long passent-elles sous terre avant d’émerger pour s’accoupler ?', 'ans', 17, null, false, null, 'cigales-periodiques', 'American Museum of Natural History', 'https://www.amnh.org/explore/news-blogs/periodical-cicadas-overview', false, 1, 'published'::public.question_status, '2026-10-20', null, 'AMNH : cycles de 13 ou 17 ans ; les adultes émergent pour se reproduire.'),
('amour-035', 'classique', 'amour', 'number'::public.question_type, 'Combien d’heures au maximum dure chaque année la période fertile d’une femelle panda géant, l’une des plus courtes du règne animal ?', 'heures', 72, null, false, null, 'panda-fertilite', 'Smithsonian’s National Zoo', 'https://nationalzoo.si.edu/animals/giant-panda-estrus-faqs', false, 3, 'published'::public.question_status, '2026-10-20', null, 'Smithsonian : 24 à 72 heures, une fois par an (printemps).'),
('amour-036', 'classique', 'amour', 'number'::public.question_type, 'Combien mesure le Taj Mahal, le plus célèbre monument jamais construit par amour (pour l’épouse de l’empereur Shah Jahan) ?', 'm', 73, null, false, null, 'taj-mahal', 'Wikipédia / Encyclopædia Britannica', 'https://en.wikipedia.org/wiki/Taj_Mahal', false, 1, 'published'::public.question_status, '2026-10-20', null, '73 m (240 ft) selon plusieurs sources concordantes ; plus de 20 000 ouvriers et artisans.'),
('amour-037', 'classique', 'amour', 'number'::public.question_type, 'Combien de lettres Juliette Drouet a-t-elle écrites à Victor Hugo entre 1833 et 1883, l’une des plus longues correspondances amoureuses de l’histoire ?', 'lettres', 22000, null, false, null, 'lettres-drouet', 'BnF', 'https://www.bnf.fr/fr/lettres-de-juliette-drouet-victor-hugo', false, 2, 'published'::public.question_status, '2026-10-20', null, 'BnF : « environ 22 000 lettres ». Un texte plus ancien de F. Naugrette disait 18 000 ; le chiffre actuel de l’édition critique est 22 000.'),
('amour-038', 'classique', 'amour', 'number'::public.question_type, 'Combien de mètres mesurait la traîne de la robe de mariée de Lady Diana en 1981, réputée la plus longue de l’histoire des mariages royaux ?', 'm', 7.6, null, false, null, 'traine-diana', 'Biography.com', 'https://www.biography.com/royalty/princess-diana-wedding-dress-facts', false, 2, 'published'::public.question_status, '2026-10-20', null, '25 pieds = 7,62 m. Record « réputé », non homologué.'),
('amour-039', 'classique', 'amour', 'number'::public.question_type, 'Combien d’années ont été mariés Elizabeth II et le prince Philip, le plus long mariage de l’histoire de la monarchie britannique ?', 'ans', 73, null, false, null, 'mariage-elizabeth-philip', 'The Himalayan Times (AP)', 'https://thehimalayantimes.com/world/queen-elizabeth-and-prince-philip-celebrate-73rd-anniversary/', false, 1, 'published'::public.question_status, '2026-10-20', null, 'Mariés le 20/11/1947, Philip meurt le 09/04/2021 : 73 ans.'),
('amour-040', 'classique', 'amour', 'number'::public.question_type, 'Combien de semaines consécutives « I Will Always Love You » de Whitney Houston est-elle restée n°1 aux États-Unis, record de l’époque pour une chanteuse ?', 'semaines', 14, null, false, null, 'whitney-houston', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/102453-most-consecutive-weeks-at-no-1-on-us-singles-chart-solo-female', false, 1, 'published'::public.question_status, '2026-10-20', null, 'GWR : 14 semaines (28/11/1992 – 27/02/1993).'),
('amour-041', 'classique', 'amour', 'number'::public.question_type, 'Combien de centimètres de côté mesure « Le Baiser » de Gustav Klimt, le tableau le plus célèbre du musée du Belvédère à Vienne ?', 'cm', 180, null, false, null, 'klimt-baiser', 'Belvedere (Vienne)', 'https://print.belvedere.at/en/?p=14549', false, 1, 'published'::public.question_status, '2026-10-20', null, 'Belvedere : 180 × 180 cm, 1908 (achevé en 1909).'),
